export interface BulkheadOptions extends Observable {
  maxConcurrent: number;
  maxQueue?: number;
  maxWaitMs?: number; // NEW: longest a call may wait for a slot
}
interface Waiter {
  resolve: () => void;
  reject: (reason: unknown) => void;
  signal?: AbortSignal;
  onAbort?: () => void;
  timer?: ReturnType<typeof setTimeout>; // NEW
}
// constructor: this.maxWaitMs = options.maxWaitMs;
// if (this.maxWaitMs !== undefined && !(Number.isFinite(this.maxWaitMs) && this.maxWaitMs > 0)) throw new RangeError("maxWaitMs must be > 0");

private waitForSlot(signal?: AbortSignal): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    const waiter: Waiter = { resolve, reject, signal };
    const leave = (reason: unknown) => {
      const i = this.queue.indexOf(waiter);
      if (i >= 0) this.queue.splice(i, 1);
      if (waiter.timer !== undefined) clearTimeout(waiter.timer);
      if (waiter.onAbort !== undefined) signal!.removeEventListener("abort", waiter.onAbort);
      reject(reason);
    };
    if (signal !== undefined) {
      waiter.onAbort = () => leave(signal.reason);
      signal.addEventListener("abort", waiter.onAbort, { once: true });
    }
    if (this.maxWaitMs !== undefined) {
      waiter.timer = setTimeout(() => leave(new BulkheadRejectedError(this.maxConcurrent, this.maxQueue)), this.maxWaitMs);
    }
    this.queue.push(waiter);
  });
}

private release(): void {
  const next = this.queue.shift();
  if (next === undefined) { this.active--; return; }
  if (next.onAbort !== undefined) next.signal!.removeEventListener("abort", next.onAbort);
  if (next.timer !== undefined) clearTimeout(next.timer); // NEW
  next.resolve();
}

