export class TimeWindow {
  private readonly calls: number[];
  private readonly failures: number[];
  private readonly epochs: number[]; // which time slot each bucket currently holds
  constructor(private readonly buckets: number, private readonly bucketMs: number, private readonly now: () => number = Date.now) {
    this.calls = new Array<number>(buckets).fill(0);
    this.failures = new Array<number>(buckets).fill(0);
    this.epochs = new Array<number>(buckets).fill(-1);
  }
  record(failed: boolean): void {
    const epoch = Math.floor(this.now() / this.bucketMs);
    const i = epoch % this.buckets;
    if (this.epochs[i] !== epoch) {
      this.epochs[i] = epoch; // the bucket held an older slot: start it fresh
      this.calls[i] = 0;
      this.failures[i] = 0;
    }
    this.calls[i]!++;
    if (failed) this.failures[i]!++;
  }
  totals(): { calls: number; failures: number } {
    const epoch = Math.floor(this.now() / this.bucketMs);
    let calls = 0;
    let failures = 0;
    for (let i = 0; i < this.buckets; i++) {
      if (epoch - this.epochs[i]! < this.buckets) {
        calls += this.calls[i]!;
        failures += this.failures[i]!;
      }
    }
    return { calls, failures };
  }
  reset(): void {
    this.epochs.fill(-1);
    this.calls.fill(0);
    this.failures.fill(0);
  }
}

