// illustrative sketch -- NOT in the repo: an AIMD limit the Bulkhead could consult
class AimdLimit {
  limit: number;
  constructor(private readonly min: number, private readonly max: number, initial: number) { this.limit = initial; }
  onSuccess(latencyMs: number, targetMs: number): void {
    if (latencyMs <= targetMs) this.limit = Math.min(this.max, this.limit + 1 / this.limit); // additive increase
  }
  onDrop(): void { // a timeout or a latency spike
    this.limit = Math.max(this.min, Math.floor(this.limit * 0.5)); // multiplicative decrease
  }
}
